const input = $input.item.json.body || {};
const language = input.language || 'zh';
const outputLanguage = input.outputLanguage || (language === 'en' ? 'English' : 'Chinese');
const overview = input.courseOverview || {};

const __out = {
  language,
  outputLanguage,
  courseTitle: input.courseTitle || overview.courseTitle || '',
  theme: input.theme || overview.theme || '',
  age: input.age || '',
  duration: input.duration || '',
  scale: input.scale || '',
  vocabulary: Array.isArray(input.vocabulary) ? input.vocabulary.join(', ') : (input.vocabulary || ''),
  grammar: Array.isArray(input.grammar) ? input.grammar.join(', ') : (input.grammar || ''),
  skills: Array.isArray(input.skills) ? input.skills.join(', ') : (input.skills || ''),
  paths: Array.isArray(input.paths) ? input.paths.join(', ') : (input.paths || ''),
  storyContext: input.storyContext || overview.overallContext || '',
  keyOutcome: input.keyOutcome || overview.finalTask || '',
  selGoals: overview.selGoals || '',
  permaGoals: overview.permaGoals || ''
};
// ─── 提示词注册表渲染（模板由后端下发：api/src/prompts，Wiki 页面可覆盖）───
const __renderPrompt = (tpl, vars) => String(tpl).replace(/\{\{\s*(\w+)\s*\}\}/g, (m, k) => (vars[k] === undefined || vars[k] === null) ? '' : String(vars[k]));
const __template = input.promptTemplate;
if (!__template) throw new Error('缺少 promptTemplate：后端提示词注册表未下发，请先部署最新 api/src/prompts 再导入本工作流');
__out.system_prompt = __renderPrompt(__template, __out);
return __out;

const raw = $input.item.json;
let tips = [];

if (Array.isArray(raw.tips)) {
  tips = raw.tips;
} else if (raw.text) {
  const text = String(raw.text).trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
  try {
    const parsed = JSON.parse(text);
    tips = Array.isArray(parsed.tips) ? parsed.tips : [];
  } catch (error) {
    tips = text.split(/\n+/).map(line => line.replace(/^[-\d.、\s]+/, '').trim());
  }
}

tips = tips
  .map(tip => String(tip || '').trim())
  .filter(Boolean)
  .slice(0, 6);

if (tips.length === 0) {
  const language = $('参数组装').first().json.language || 'zh';
  const fallbackTipsZh = [
    '希望故事情境更有悬念，让学生从一封任务信或线索卡进入挑战。',
    '希望Execute阶段加入小组合作竞赛，让最终产出更有挑战性。',
    '希望语言工具箱更聚焦口语输出，增加可反复套用的课堂句型。',
    '希望成长目标更突出团队协作、情绪表达和解决问题后的成就感。'
  ];
  const fallbackTipsEn = [
    'Make the story context more suspenseful, with students entering through a mission letter or clue card.',
    'Add a team-based challenge in the Execute phase to make the final output more meaningful.',
    'Make the language toolkit focus more on oral output and reusable classroom sentence patterns.',
    'Strengthen growth goals around teamwork, emotional expression, and a sense of accomplishment.'
  ];
  tips = language === 'en' ? fallbackTipsEn : fallbackTipsZh;
}

return { tips };
